<script setup lang="ts">
import { computed, ref, watch } from 'vue'

type ColumnId = 'backlog' | 'doing' | 'done'
type Priority = 'Alta' | 'Media' | 'Baixa'
interface Member { id: number; name: string; initials: string; color: string; email: string }
interface Comment { id: number; author: string; initials: string; text: string; time: string }
interface Task { id: number; title: string; description: string; priority: Priority; tag: string; tagColor?: string; column: string; assigneeId: number; dueDate?: string; archived?: boolean; comments: Comment[] }
interface Board { id: number; name: string; description: string; color: string; tasks: Task[] }
interface Activity { id: number; boardId: number; actorId: number; action: string; taskId?: number; taskTitle: string; detail?: string; createdAt: string }

const columns = [
  { id: 'backlog' as ColumnId, title: 'A fazer', color: 'coral' },
  { id: 'doing' as ColumnId, title: 'Em andamento', color: 'gold' },
  { id: 'done' as ColumnId, title: 'Concluido', color: 'mint' },
]
const customColumns = ref<{ id: string; title: string; color: string }[]>([])
const members: Member[] = [
  { id: 1, name: 'Gusstavo Tucci', initials: 'GT', color: '#e85e46', email: 'gusstavo@taskroom.dev' },
  { id: 2, name: 'Marina Costa', initials: 'MC', color: '#4a9d7b', email: 'marina@taskroom.dev' },
  { id: 3, name: 'Rafael Lima', initials: 'RL', color: '#d9a441', email: 'rafael@taskroom.dev' },
  { id: 4, name: 'Ana Souza', initials: 'AS', color: '#6886b2', email: 'ana@taskroom.dev' },
]
const seed = (): Board[] => [{ id: 1, name: 'Produto', description: 'Planejamento do proximo lancamento', color: '#e85e46', tasks: [
  { id: 1, title: 'Mapear fluxo do usuario', description: 'Entender os pontos principais da experiencia.', priority: 'Alta', tag: 'Pesquisa', column: 'backlog', assigneeId: 2, comments: [{ id: 1, author: 'Marina Costa', initials: 'MC', text: 'Vou transformar os achados em um mapa visual.', time: 'ha 18 min' }] },
  { id: 2, title: 'Criar wireframes', description: 'Rascunhar as telas essenciais do produto.', priority: 'Media', tag: 'Design', column: 'backlog', assigneeId: 4, comments: [] },
  { id: 3, title: 'Configurar componentes', description: 'Montar a base visual reutilizavel em Vue.', priority: 'Alta', tag: 'Desenvolvimento', column: 'doing', assigneeId: 1, comments: [{ id: 2, author: 'Gusstavo Tucci', initials: 'GT', text: 'A base esta pronta para revisao.', time: 'ha 42 min' }] },
  { id: 4, title: 'Revisar tipografia', description: 'Conferir hierarquia e legibilidade dos textos.', priority: 'Baixa', tag: 'Design', column: 'done', assigneeId: 3, comments: [] },
] }, { id: 2, name: 'Marketing', description: 'Campanha de lancamento', color: '#4a9d7b', tasks: [] }]

const stored = localStorage.getItem('taskroom-workspace')
const boards = ref<Board[]>(stored ? JSON.parse(stored) : seed())
const storedColumns = localStorage.getItem('taskroom-columns')
if (storedColumns) customColumns.value = JSON.parse(storedColumns)
const storedActivities = localStorage.getItem('taskroom-activities')
const activities = ref<Activity[]>(storedActivities ? JSON.parse(storedActivities) : [])
if (!storedActivities) activities.value.push({ id: Date.now(), boardId: 1, actorId: 2, action: 'moveu a tarefa', taskId: 1, taskTitle: 'Mapear fluxo do usuario', detail: 'para A fazer', createdAt: new Date(Date.now() - 18 * 60000).toISOString() })
const activeBoardId = ref(1)
const search = ref('')
const priorityFilter = ref<'Todas' | Priority>('Todas')
const tagFilter = ref('Todas')
const assigneeFilter = ref(0)
const viewMode = ref<'board' | 'list' | 'calendar'>('board')
const groupBy = ref<'none' | 'project' | 'category'>('none')
const showArchived = ref(false)
const newColumnTitle = ref('')
const isColumnFormOpen = ref(false)
const showActivityHistory = ref(false)
const selectedTask = ref<Task | null>(null)
const isFormOpen = ref(false)
const isBoardFormOpen = ref(false)
const showMembers = ref(false)
const showLogin = ref(false)
const copied = ref(false)
const feedback = ref('')
const draggedTaskId = ref<number | null>(null)
const newTask = ref({ title: '', description: '', priority: 'Media' as Priority, tag: 'Geral', tagColor: '#e85e46', assigneeId: 1, dueDate: '' })
const newBoardName = ref('')
const newComment = ref('')
const isLoggedIn = ref(true)
let feedbackTimer: number | undefined

const emptyBoard: Board = { id: 0, name: 'Quadro', description: 'Novo espaco de colaborao', color: '#6886b2', tasks: [] }
const activeBoard = computed<Board>(() => boards.value.find((board) => board.id === activeBoardId.value) || boards.value[0] || emptyBoard)
const allTasks = computed(() => activeBoard.value?.tasks || [])
const activeActivities = computed(() => activities.value.filter((activity) => activity.boardId === activeBoard.value.id).slice().reverse())
const availableTags = computed(() => [...new Set(allTasks.value.map((task) => task.tag))])
const visibleColumns = computed(() => [...columns, ...customColumns.value])
const visibleTasks = computed(() => allTasks.value.filter((task) => {
  const query = search.value.toLowerCase()
  return !task.archived === !showArchived.value && `${task.title} ${task.description} ${task.tag}`.toLowerCase().includes(query) && (priorityFilter.value === 'Todas' || task.priority === priorityFilter.value) && (tagFilter.value === 'Todas' || task.tag === tagFilter.value) && (!assigneeFilter.value || task.assigneeId === assigneeFilter.value)
}))
const taskGroups = computed(() => {
  if (groupBy.value === 'none') return [{ label: 'Todas as tarefas', tasks: visibleTasks.value }]
  if (groupBy.value === 'project') return [{ label: activeBoard.value.name, tasks: visibleTasks.value }]
  return availableTags.value.map((tag) => ({ label: tag, tasks: visibleTasks.value.filter((task) => task.tag === tag) })).filter((group) => group.tasks.length)
})
const completedCount = computed(() => allTasks.value.filter((task) => task.column === 'done' && !task.archived).length)
const archivedCount = computed(() => allTasks.value.filter((task) => task.archived).length)
const totalComments = computed(() => allTasks.value.reduce((total, task) => total + task.comments.length, 0))
watch(boards, (value) => localStorage.setItem('taskroom-workspace', JSON.stringify(value)), { deep: true })
watch(customColumns, (value) => localStorage.setItem('taskroom-columns', JSON.stringify(value)), { deep: true })
watch(activities, (value) => localStorage.setItem('taskroom-activities', JSON.stringify(value)), { deep: true })
function tasksForColumn(column: string) { return visibleTasks.value.filter((task) => task.column === column) }
function memberFor(id: number): Member { return members.find((member) => member.id === id) || members[0]! }
function tagColorFor(task: Task) { return task.tagColor || ({ Pesquisa: '#d9a441', Design: '#6886b2', Desenvolvimento: '#4a9d7b' }[task.tag] || '#e85e46') }
function columnColorFor(color: string) { return color.startsWith('#') ? undefined : color }
function showFeedback(message: string) { feedback.value = message; window.clearTimeout(feedbackTimer); feedbackTimer = window.setTimeout(() => { feedback.value = '' }, 2600) }
function recordActivity(action: string, taskTitle: string, taskId?: number, detail?: string) { activities.value.push({ id: Date.now(), boardId: activeBoard.value.id, actorId: 1, action, taskId, taskTitle, detail, createdAt: new Date().toISOString() }) }
function relativeTime(date: string) { const minutes = Math.max(0, Math.round((Date.now() - new Date(date).getTime()) / 60000)); return minutes < 1 ? 'agora' : minutes === 1 ? 'ha 1 min' : minutes < 60 ? `ha ${minutes} min` : `ha ${Math.round(minutes / 60)} h` }
function addTask() { if (!newTask.value.title.trim()) return showFeedback('De um nome da tarefa antes de adicionar.'); const task = { id: Date.now(), title: newTask.value.title.trim(), description: newTask.value.description.trim() || 'Sem descrio', priority: newTask.value.priority, tag: newTask.value.tag.trim() || 'Geral', tagColor: newTask.value.tagColor, column: 'backlog', assigneeId: newTask.value.assigneeId, dueDate: newTask.value.dueDate || undefined, comments: [] }; activeBoard.value.tasks.unshift(task); recordActivity('criou a tarefa', task.title, task.id); newTask.value = { title: '', description: '', priority: 'Media', tag: 'Geral', tagColor: '#e85e46', assigneeId: 1, dueDate: '' }; isFormOpen.value = false; showFeedback('Tarefa adicionada ao quadro.') }
function addBoard() { if (!newBoardName.value.trim()) return; const board: Board = { id: Date.now(), name: newBoardName.value.trim(), description: 'Novo espaco de colaborao', color: '#6886b2', tasks: [] }; boards.value.push(board); activeBoardId.value = board.id; newBoardName.value = ''; isBoardFormOpen.value = false; showFeedback('Quadro criado.') }
function deleteTask(id: number) { const task = allTasks.value.find((item) => item.id === id); if (task) recordActivity('excluiu a tarefa', task.title, task.id); activeBoard.value.tasks = activeBoard.value.tasks.filter((task) => task.id !== id); selectedTask.value = null; showFeedback('Tarefa excluida.') }
function moveTask(column: string) { const task = allTasks.value.find((item) => item.id === draggedTaskId.value); if (task && task.column !== column) { const destination = visibleColumns.value.find((item) => item.id === column)?.title || column; task.column = column; recordActivity('moveu a tarefa', task.title, task.id, `para ${destination}`); showFeedback(`Tarefa movida para ${destination}.`) }; draggedTaskId.value = null }
function archiveTask(task: Task) { if (!task.archived && task.column !== 'done') return showFeedback('Apenas tarefas concluídas podem ser arquivadas.'); task.archived = !task.archived; recordActivity(task.archived ? 'arquivou a tarefa' : 'restaurou a tarefa', task.title, task.id); showFeedback(task.archived ? 'Tarefa arquivada.' : 'Tarefa restaurada.') }
function addColumn() { const title = newColumnTitle.value.trim(); if (!title) return; customColumns.value.push({ id: `custom-${Date.now()}`, title, color: '#6886b2' }); newColumnTitle.value = ''; isColumnFormOpen.value = false; recordActivity('criou a coluna', title, undefined, 'coluna personalizada'); showFeedback('Coluna personalizada criada.') }
function formatDate(date?: string) { if (!date) return 'Sem data'; return new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'short' }).format(new Date(`${date}T12:00:00`)) }
function addComment() { if (!selectedTask.value || !newComment.value.trim()) return; selectedTask.value.comments.push({ id: Date.now(), author: 'Gusstavo Tucci', initials: 'GT', text: newComment.value.trim(), time: 'agora' }); recordActivity('comentou na tarefa', selectedTask.value.title, selectedTask.value.id); newComment.value = ''; showFeedback('Comentario adicionado ao historico.') }
async function copyLink() { await navigator.clipboard?.writeText(`${window.location.origin}/share/${activeBoard.value.id}`); copied.value = true; showFeedback('Link de compartilhamento copiado.'); window.setTimeout(() => { copied.value = false }, 1800) }
function login() { isLoggedIn.value = true; showLogin.value = false; showFeedback('Sincronizao ativada para Gusstavo.') }
</script>

<template>
  <main class="app-shell">
    <aside class="sidebar">
      <div class="brand"><span class="brand-mark">+</span><strong>Taskroom</strong></div>
      <div class="workspace-switcher"><span class="workspace-icon">P</span><div><small>Workspace</small><b>Produto digital</b></div><span>R</span></div>
      <p class="nav-label">Seus quadros <button class="small-icon" aria-label="Criar quadro" @click="isBoardFormOpen = !isBoardFormOpen">+</button></p>
      <form v-if="isBoardFormOpen" class="new-board" @submit.prevent="addBoard"><input v-model="newBoardName" autofocus placeholder="Nome do quadro" /><button aria-label="Criar"> </button></form>
      <nav class="board-nav"><button v-for="board in boards" :key="board.id" :class="{ active: activeBoardId === board.id }" @click="activeBoardId = board.id"><span class="board-dot" :style="{ background: board.color }"></span>{{ board.name }}<span class="board-count">{{ board.tasks.length }}</span></button></nav>
      <div class="sidebar-bottom"><button class="sync-button" @click="showLogin = true"><span class="sync-dot" :class="{ online: isLoggedIn }"></span><span><b>{{ isLoggedIn ? 'Sincronizado' : 'Modo local' }}</b><small>{{ isLoggedIn ? 'Banco de dados conectado' : 'Entrar para sincronizar' }}</small></span><span>:</span></button><div class="profile"><span class="avatar" style="background:#e85e46">GT</span><span><b>Gusstavo Tucci</b><small>Administrador</small></span><button aria-label="Opes">"""</button></div></div>
    </aside>
    <section class="content">
      <header class="topbar"><div class="breadcrumbs"><span>Workspace</span><b>/</b><strong>{{ activeBoard.name }}</strong></div><div class="top-actions"><div class="presence"><span class="presence-dot"></span> 4 online</div><div class="member-stack"><span v-for="member in members.slice(0, 3)" :key="member.id" class="avatar mini" :style="{ background: member.color }">{{ member.initials }}</span><button class="avatar add-member" aria-label="Adicionar membros" @click="showMembers = !showMembers">+</button></div><button class="share-button" @click="copyLink">R {{ copied ? 'Copiado' : 'Compartilhar' }}</button></div></header>
      <div v-if="showMembers" class="members-popover"><strong>Membros do quadro</strong><div v-for="member in members" :key="member.id" class="member-row"><span class="avatar mini" :style="{ background: member.color }">{{ member.initials }}</span><span><b>{{ member.name }}</b><small>{{ member.email }}</small></span><span class="member-check">S</span></div><button class="invite-button" @click="showFeedback('Convite pronto para ser enviado.')">+ Convidar por e-mail</button></div>
      <section class="page-heading"><div><span class="eyebrow">Quadro colaborativo</span><h1>{{ activeBoard.name }} <span class="privacy">R Privado</span></h1><p>{{ activeBoard.description }}</p></div><button class="primary-button" @click="isFormOpen = !isFormOpen"><span>+</span> Nova tarefa</button></section>
      <form v-if="isFormOpen" class="task-form" @submit.prevent="addTask"><input v-model="newTask.title" autofocus placeholder="Nome da tarefa" /><input v-model="newTask.description" placeholder="Descrio breve" /><input v-model="newTask.tag" placeholder="Etiqueta" /><input v-model="newTask.dueDate" type="date" aria-label="Data de entrega" /><label class="color-input">Cor <input v-model="newTask.tagColor" type="color" /></label><select v-model="newTask.priority"><option>Alta</option><option>Media</option><option>Baixa</option></select><select v-model="newTask.assigneeId"><option v-for="member in members" :key="member.id" :value="member.id">{{ member.name }}</option></select><button class="primary-button">Adicionar</button></form>
      <section class="organization-toolbar"><div class="view-switcher"><button :class="{ active: viewMode === 'board' }" @click="viewMode = 'board'">Quadro</button><button :class="{ active: viewMode === 'list' }" @click="viewMode = 'list'">Lista</button><button :class="{ active: viewMode === 'calendar' }" @click="viewMode = 'calendar'">Calendario</button></div><label class="search-box">R" <input v-model="search" placeholder="Buscar tarefas..." /></label><select v-model="priorityFilter"><option>Todas</option><option>Alta</option><option>Media</option><option>Baixa</option></select><select v-model="tagFilter"><option>Todas</option><option v-for="tag in availableTags" :key="tag">{{ tag }}</option></select><select v-model="assigneeFilter"><option :value="0">Todos responsaveis</option><option v-for="member in members" :key="member.id" :value="member.id">{{ member.name }}</option></select><select v-model="groupBy"><option value="none">Sem agrupamento</option><option value="project">Agrupar por projeto</option><option value="category">Agrupar por categoria</option></select><button class="archive-toggle" :class="{ active: showArchived }" @click="showArchived = !showArchived">{{ showArchived ? 'Ativas' : `Arquivadas (${archivedCount})` }}</button><span class="progress"><b>{{ completedCount }}/{{ allTasks.length }}</b> concluidas</span></section>
      <div class="column-actions"><button class="text-button" @click="isColumnFormOpen = !isColumnFormOpen">+ Coluna personalizada</button><form v-if="isColumnFormOpen" @submit.prevent="addColumn"><input v-model="newColumnTitle" autofocus placeholder="Nome da coluna" /><button class="primary-button">Criar</button></form></div>
      <section v-if="viewMode === 'board'" class="board"><article v-for="column in visibleColumns" :key="column.id" :data-column="column.id" :class="['column', { 'is-drop-target': draggedTaskId !== null }]" @dragover.prevent @drop="moveTask(column.id)"><div class="column-heading"><div><span :class="['status-dot', columnColorFor(column.color)]" :style="{ background: column.color.startsWith('#') ? column.color : undefined }"></span><h2>{{ column.title }}</h2></div><span class="count">{{ tasksForColumn(column.id).length }}</span></div><div class="task-list"><div v-for="task in tasksForColumn(column.id)" :key="task.id" class="task-card" :class="{ 'is-dragging': draggedTaskId === task.id }" draggable="true" @dragstart="draggedTaskId = task.id" @dragend="draggedTaskId = null" @click="selectedTask = task"><div class="task-card-top"><span :class="['priority', task.priority.toLowerCase()]">{{ task.priority }}</span><button class="delete-button" aria-label="Excluir tarefa" @click.stop="deleteTask(task.id)"></button></div><h3>{{ task.title }}</h3><p>{{ task.description }}</p><footer><span class="tag" :style="{ borderColor: tagColorFor(task), color: tagColorFor(task) }">{{ task.tag }}</span><span class="due-date">{{ formatDate(task.dueDate) }}</span><span v-if="task.comments.length" class="comment-count">R {{ task.comments.length }}</span><button class="archive-button" :aria-label="task.archived ? 'Restaurar tarefa' : 'Arquivar tarefa'" @click.stop="archiveTask(task)">{{ task.archived ? '↶' : '⌄' }}</button><span class="assignee avatar mini" :style="{ background: memberFor(task.assigneeId).color }">{{ memberFor(task.assigneeId).initials }}</span></footer></div><div v-if="tasksForColumn(column.id).length === 0" class="empty-state">Solte uma tarefa aqui</div></div></article></section>
      <section v-else-if="viewMode === 'list'" class="list-view"><div v-for="group in taskGroups" :key="group.label" class="task-group"><h3>{{ group.label }} <span>{{ group.tasks.length }}</span></h3><div v-for="task in group.tasks" :key="task.id" class="list-row" @click="selectedTask = task"><span :class="['priority', task.priority.toLowerCase()]">{{ task.priority }}</span><strong>{{ task.title }}</strong><span class="tag" :style="{ borderColor: tagColorFor(task), color: tagColorFor(task) }">{{ task.tag }}</span><span>{{ visibleColumns.find((column) => column.id === task.column)?.title }}</span><span>{{ memberFor(task.assigneeId).name }}</span><span>{{ formatDate(task.dueDate) }}</span><button class="archive-button" @click.stop="archiveTask(task)">{{ task.archived ? 'Restaurar' : 'Arquivar' }}</button></div></div><p v-if="!visibleTasks.length" class="empty-state">Nenhuma tarefa encontrada.</p></section>
      <section v-else class="calendar-view"><div class="calendar-head"><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sab</span><span>Dom</span></div><div class="calendar-grid"><div v-for="day in 35" :key="day" class="calendar-day"><small>{{ day <= 31 ? day : '' }}</small><button v-for="task in visibleTasks.filter((item) => item.dueDate && Number(item.dueDate.slice(-2)) === day)" :key="task.id" @click="selectedTask = task">{{ task.title }}</button></div></div></section>
      <section class="activity-strip"><button class="activity-summary" @click="showActivityHistory = !showActivityHistory"><span class="activity-icon"> </span><span><b>Atividade recente</b><small v-if="activeActivities[0]">{{ memberFor(activeActivities[0].actorId).name }} {{ activeActivities[0].action }} “{{ activeActivities[0].taskTitle }}” {{ activeActivities[0].detail || '' }} · {{ relativeTime(activeActivities[0].createdAt) }}</small><small v-else>Nenhuma atividade registrada neste quadro.</small></span></button><div class="activity-stat"><b>{{ activeActivities.length }}</b> alterações <button class="text-button" @click="showActivityHistory = !showActivityHistory">{{ showActivityHistory ? 'Fechar' : 'Ver histórico' }}</button></div></section>
      <section v-if="showActivityHistory" class="activity-history"><header><div><span class="eyebrow">Registro do quadro</span><h2>Histórico de atividades</h2></div><span>{{ activeActivities.length }} eventos</span></header><article v-for="activity in activeActivities" :key="activity.id" class="activity-item"><span class="avatar mini" :style="{ background: memberFor(activity.actorId).color }">{{ memberFor(activity.actorId).initials }}</span><div><p><strong>{{ memberFor(activity.actorId).name }}</strong> {{ activity.action }} <b>{{ activity.taskTitle }}</b></p><small>{{ activity.detail || 'Alteração registrada' }} · {{ relativeTime(activity.createdAt) }}</small></div></article><p v-if="!activeActivities.length" class="empty-state">As próximas alterações aparecerão aqui.</p></section>
    </section>
    <Transition name="modal"><div v-if="selectedTask" class="modal-backdrop" @click.self="selectedTask = null"><section class="task-modal"><button class="modal-close" aria-label="Fechar detalhes" @click="selectedTask = null"></button><span :class="['priority', selectedTask!.priority.toLowerCase()]">{{ selectedTask!.priority }}</span><h2>{{ selectedTask!.title }}</h2><p>{{ selectedTask!.description }}</p><div class="detail-grid"><div><small>Responsavel</small><b><span class="avatar mini" :style="{ background: memberFor(selectedTask!.assigneeId).color }">{{ memberFor(selectedTask!.assigneeId).initials }}</span>{{ memberFor(selectedTask!.assigneeId).name }}</b></div><div><small>Status</small><b>{{ visibleColumns.find((column) => column.id === selectedTask?.column)?.title }}</b></div></div><hr /><h3>Comentarios <span>{{ selectedTask!.comments.length }}</span></h3><div class="comments"><div v-for="comment in selectedTask!.comments" :key="comment.id" class="comment"><span class="avatar mini" style="background:#e85e46">{{ comment.initials }}</span><div><b>{{ comment.author }} <small>{{ comment.time }}</small></b><p>{{ comment.text }}</p></div></div><p v-if="!selectedTask!.comments.length" class="no-comments">Ainda no ha comentarios.</p></div><form class="comment-form" @submit.prevent="addComment"><input v-model="newComment" placeholder="Escreva um comentrio..." /><button aria-label="Enviar comentrio"> </button></form></section></div></Transition>
    <Transition name="toast"><p v-if="feedback" class="feedback" role="status">{{ feedback }}</p></Transition>
    <div v-if="showLogin" class="modal-backdrop" @click.self="showLogin = false"><section class="login-modal"><span class="brand-mark">+</span><h2>Entrar no Taskroom</h2><p>Conecte sua conta para manter quadros e alteraes sincronizados.</p><input placeholder="seu@email.com" value="gusstavo@taskroom.dev" /><input type="password" placeholder="Senha" value="taskroom" /><button class="primary-button" @click="login">Entrar e sincronizar</button><button class="text-button" @click="showLogin = false">Continuar no modo local</button></section></div>
  </main>
 </template>

<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');
:root { font-family: 'DM Sans', sans-serif; color: #f4f0e9; background: #16191b; font-synthesis: none; } * { box-sizing: border-box; } body { margin: 0; min-width: 320px; background: #16191b; } button, input, select { font: inherit; } button { cursor: pointer; }
